package com.alsafa.native4;
import android.app.Activity;import android.view.View;import android.widget.TextView;import com.alsafa.native4.core.*;
/** Binds an explicit page sync control to Native4-only sync; no global layout-id dependency. */
public final class SyncButtonBinder{private SyncButtonBinder(){}public static void bind(Activity a,CoreDb db,TextView status,Runnable refresh,View button){if(button==null)return;button.setOnClickListener(v->{status.setText("جاري تشغيل مزامنة Native4 الجديدة...");Native4SyncRunner.run(a,db,new Native4SyncRunner.Callback(){public void done(Native4SyncCoordinator.Result r){status.setText(Native4SyncRunner.summary(r));if(refresh!=null)refresh.run();}public void failed(Exception e){status.setText("تعذرت مزامنة Native4: "+(e.getMessage()==null?e.getClass().getSimpleName():e.getMessage())+" — البيانات المحلية محفوظة");if(refresh!=null)refresh.run();}});});}}